static void em_fuzz_command_and_message_id(
     const rule_info_t *rule, int verdict, uint64_t timestamp,
     uint64_t counter, const mmt_array_t * const trace ){
     int is_string = 0;
     // Set command field to N-DELETE-RQ (0x0150)
     uint16_t cmd_val = 0x0150;
     replace_dicom_attribute(701, 14, &cmd_val, is_string);
     // Set message ID to 9999
     uint16_t msg_val = 9999;
     replace_dicom_attribute(701, 18, &msg_val, is_string);
     forward_packet();
}
